class Solution {
public:
    int countTriplets(vector<int>& nums) {
        const int M = 1 << 16;
        vector<int> cnt(M), f(M);
        for (int a : nums)
            for (int b : nums)
                cnt[a & b]++;
        f = cnt;
        for (int b = 0; b < 16; ++b)
            for (int mask = 0; mask < M; ++mask)
                if (mask & (1 << b))
                    f[mask] += f[mask ^ (1 << b)];
        int ans = 0;
        for (int c : nums) ans += f[(M - 1) ^ c];
        return ans;
    }
};

