class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        M = 1 << 16
        cnt = [0] * M
        for a in nums:
            for b in nums:
                cnt[a & b] += 1
        f = cnt[:]
        for b in range(16):
            bit = 1 << b
            for mask in range(M):
                if mask & bit:
                    f[mask] += f[mask ^ bit]
        ans = 0
        for c in nums:
            ans += f[(M - 1) ^ c]
        return ans

