class Solution {
public:
    int minimumScore(vector<int>& nums, vector<vector<int>>& edges) {
        int n = (int)nums.size();
        vector<vector<int>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        vector<int> xors(n), tin(n), tout(n);
        int timer = 0;
        function<void(int,int)> dfs = [&](int u, int p) {
            tin[u] = timer++;
            xors[u] = nums[u];
            for (int v : g[u]) if (v != p) {
                dfs(v, u);
                xors[u] ^= xors[v];
            }
            tout[u] = timer;
        };
        dfs(0, -1);
        int total = xors[0];
        auto anc = [&](int a, int b) { return tin[a] <= tin[b] && tin[b] < tout[a]; };
        int ans = INT_MAX;
        for (int i = 1; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int a, b, c;
                if (anc(i, j)) {
                    a = xors[j]; b = xors[i] ^ xors[j]; c = total ^ xors[i];
                } else if (anc(j, i)) {
                    a = xors[i]; b = xors[j] ^ xors[i]; c = total ^ xors[j];
                } else {
                    a = xors[i]; b = xors[j]; c = total ^ xors[i] ^ xors[j];
                }
                int mx = max(a, max(b, c));
                int mn = min(a, min(b, c));
                ans = min(ans, mx - mn);
            }
        }
        return ans;
    }
};

