from typing import List

class Solution:
    def minimumScore(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        xors = [0] * n
        tin = [0] * n
        tout = [0] * n
        timer = 0

        def dfs(u: int, p: int) -> None:
            nonlocal timer
            tin[u] = timer
            timer += 1
            xors[u] = nums[u]
            for v in g[u]:
                if v != p:
                    dfs(v, u)
                    xors[u] ^= xors[v]
            tout[u] = timer

        dfs(0, -1)
        total = xors[0]

        def anc(a: int, b: int) -> bool:
            return tin[a] <= tin[b] < tout[a]

        ans = 10 ** 18
        for i in range(1, n):
            for j in range(i + 1, n):
                if anc(i, j):
                    a, b, c = xors[j], xors[i] ^ xors[j], total ^ xors[i]
                elif anc(j, i):
                    a, b, c = xors[i], xors[j] ^ xors[i], total ^ xors[j]
                else:
                    a, b, c = xors[i], xors[j], total ^ xors[i] ^ xors[j]
                ans = min(ans, max(a, b, c) - min(a, b, c))
        return ans

