class Solution {
public:
    int minFlips(vector<vector<int>>& mat) {
        int m = (int)mat.size(), n = (int)mat[0].size();
        int start = 0;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (mat[i][j]) start |= 1 << (i * n + j);
        const int di[5] = {0, 1, -1, 0, 0};
        const int dj[5] = {0, 0, 0, 1, -1};
        auto flip = [&](int state, int i, int j) {
            for (int k = 0; k < 5; ++k) {
                int ni = i + di[k], nj = j + dj[k];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n)
                    state ^= 1 << (ni * n + nj);
            }
            return state;
        };
        int N = 1 << (m * n);
        vector<int> dist(N, -1);
        queue<int> q;
        q.push(start);
        dist[start] = 0;
        while (!q.empty()) {
            int s = q.front(); q.pop();
            if (s == 0) return dist[s];
            for (int i = 0; i < m; ++i)
                for (int j = 0; j < n; ++j) {
                    int ns = flip(s, i, j);
                    if (dist[ns] == -1) {
                        dist[ns] = dist[s] + 1;
                        q.push(ns);
                    }
                }
        }
        return -1;
    }
};

