from collections import deque
from typing import List

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j]:
                    start |= 1 << (i * n + j)
        dirs = ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1))

        def flip(state: int, i: int, j: int) -> int:
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n:
                    state ^= 1 << (ni * n + nj)
            return state

        q = deque([start])
        dist = {start: 0}
        while q:
            s = q.popleft()
            if s == 0:
                return dist[s]
            for i in range(m):
                for j in range(n):
                    ns = flip(s, i, j)
                    if ns not in dist:
                        dist[ns] = dist[s] + 1
                        q.append(ns)
        return -1

