class BSTIterator {
    private Deque<TreeNode> st = new ArrayDeque<>();

    public BSTIterator(TreeNode root) {
        pushLeft(root);
    }

    private void pushLeft(TreeNode u) {
        while (u != null) {
            st.push(u);
            u = u.left;
        }
    }

    public int next() {
        TreeNode u = st.pop();
        pushLeft(u.right);
        return u.val;
    }

    public boolean hasNext() {
        return !st.isEmpty();
    }
}

