# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right

from typing import Optional

class BSTIterator:
    def __init__(self, root: Optional[TreeNode]):
        self.st: list[TreeNode] = []
        self._push_left(root)

    def _push_left(self, u: Optional[TreeNode]) -> None:
        while u:
            self.st.append(u)
            u = u.left

    def next(self) -> int:
        u = self.st.pop()
        self._push_left(u.right)
        return u.val

    def hasNext(self) -> bool:
        return bool(self.st)

