                v.word = None
            board[i][j] = "#"
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and board[ni][nj] != "#":
                    dfs(ni, nj, v)
            board[i][j] = c
            if not v.next and v.word is None:
                u.next.pop(c, None)

        for i in range(m):
            for j in range(n):
                dfs(i, j, root)
        return ans

