        int u = 0;
        for (int b = 30; b >= 0; --b) {
            int bit = (v >> b) & 1;
            if (tr[u].ch[bit] == -1) {
                tr[u].ch[bit] = (int)tr.size();
                tr.push_back(Node());
            }
            u = tr[u].ch[bit];
        }
