        int u = 0, ans = 0;
        for (int b = 30; b >= 0; --b) {
            int bit = (x >> b) & 1;
            int want = bit ^ 1;
            if (tr[u].ch[want] != -1) {
                ans |= 1 << b;
                u = tr[u].ch[want];
            } else {
                u = tr[u].ch[bit];
            }
        }
        return ans;
    }

