class DSU {
    vector<int> p, r;
public:
    DSU(int n) : p(n), r(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        if (p[x] != x) p[x] = find(p[x]);
        return p[x];
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
    }
};

class Solution {
public:
    int numberOfGoodPaths(vector<int>& vals, vector<vector<int>>& edges) {
        int n = (int)vals.size();
        vector<vector<int>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        map<int, vector<int>> byVal;
        for (int i = 0; i < n; ++i) byVal[vals[i]].push_back(i);
        DSU dsu(n);
        int ans = 0;
        for (auto& [v, nodes] : byVal) {
            for (int x : nodes)
                for (int y : g[x])
                    if (vals[y] <= v) dsu.unite(x, y);
            unordered_map<int, int> cnt;
            for (int x : nodes) cnt[dsu.find(x)]++;
            for (auto& [_, c] : cnt) ans += c * (c + 1) / 2;
        }
        return ans;
    }
};

