        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
        }
        TreeMap<Integer, List<Integer>> byVal = new TreeMap<>();
        for (int i = 0; i < n; i++)
            byVal.computeIfAbsent(vals[i], k -> new ArrayList<>()).add(i);
