            List<Integer> nodes = byVal.get(v);
            for (int x : nodes)
                for (int y : g[x])
                    if (vals[y] <= v) dsu.unite(x, y);
            Map<Integer, Integer> cnt = new HashMap<>();
            for (int x : nodes) cnt.merge(dsu.find(x), 1, Integer::sum);
            for (int c : cnt.values()) ans += c * (c + 1) / 2;
        }
        return ans;
    }
