        know = [False] * n
        know[0] = know[firstPerson] = True
        meetings.sort(key=lambda x: x[2])
        i, m = 0, len(meetings)
        while i < m:
            t = meetings[i][2]
            dsu = DSU()
            people = []
            while i < m and meetings[i][2] == t:
                x, y, _ = meetings[i]
                dsu.union(x, y)
